-- ⛔ Sekvence za pevnými id (naměřeno 2026-09-14): řádky výše nesou id z produkce,
-- sekvence ale zůstala na začátku → první INSERT bez id (admin, migrace, test) na
-- čisté instanci padl na delivery_transition_rules_pkey. Posun jen DOPŘEDU
-- (max(id) i dosavadní last_value), idempotentní. Sekvence jménem přes ::regclass,
-- NE pg_get_serial_sequence(): ta pro sekvenci bez OWNED BY vrací NULL a setval(NULL)
-- by potichu nic neudělal. Týž příkaz je v heals.sql pro běžící instance.
-- Hlídá src/tests/db/sekvence-nezaostava-za-daty.runtime.test.ts.
SELECT setval(
  'public.delivery_transition_rules_id_seq'::regclass,
  GREATEST(
    (SELECT COALESCE(max(id), 0) FROM public.delivery_transition_rules),
    (SELECT COALESCE(last_value, 0) FROM pg_sequences
      WHERE schemaname = 'public' AND sequencename = 'delivery_transition_rules_id_seq'),
    1),
  EXISTS (SELECT 1 FROM public.delivery_transition_rules)
    OR EXISTS (SELECT 1 FROM pg_sequences
      WHERE schemaname = 'public' AND sequencename = 'delivery_transition_rules_id_seq' AND last_value IS NOT NULL)
);

-- ============================================================================
-- ai_model_registry (14 models from archived migrations)
-- ============================================================================
-- cached_input_price_per_m = prompt-cache READ rate (odysseus G1). Sourced from
-- public provider pricing (2026-07-08). Per-provider cache-read discount vs base
-- input rate:
--   anthropic → 0.10× (90% off; write is 1.25× and is not stored — costAggregator
--               falls back to input for writes). Sources: platform.claude.com/docs/pricing
--   openai    → 0.10× current-gen (gpt-5/o-series per developers.openai.com/api/docs/pricing),
--               0.50× legacy gpt-4o family, 0.25× o-mini reasoning tier.
--   google    → 0.10× Gemini 2.5+ (ai.google.dev/gemini-api/docs/pricing), 0.25× 2.0.
--   xai       → ~0.15× (aipricing.guru/xai-pricing; grok is eval_status=pending, approximate).
--   vllm/local→ 0 (self-hosted, no per-token cost).
-- These are cold-start DEFAULTS; the discovery scan (upsert_discovered_model, now
-- carrying p_cached_input_price_per_m) is authoritative and overrides going forward.
-- Live DBs are backfilled by heals.sql (ON CONFLICT DO NOTHING won't touch existing rows).
