  ('openai', 'gpt-5-mini', 'GPT-5 Mini', 'gpt-5', true, false, true, 128000, 16384, 0.1500, 0.6000, 0.0150, 'approved'),
  ('openai', 'gpt-4o', 'GPT-4o', 'gpt-4o', false, true, true, 128000, 16384, 2.5000, 10.0000, 1.2500, 'approved'),
  ('openai', 'gpt-4o-mini', 'GPT-4o Mini', 'gpt-4o', false, true, true, 128000, 16384, 0.1500, 0.6000, 0.0750, 'approved'),
  ('openai', 'o4-mini', 'O4 Mini', 'o4', true, true, true, 200000, 100000, 1.1000, 4.4000, 0.2750, 'tested'),
  ('openai', 'o3-mini', 'O3 Mini', 'o3', true, false, true, 200000, 100000, 1.1000, 4.4000, 0.2750, 'tested'),
  -- Anthropic (cache read 0.10× base input)
  ('anthropic', 'claude-sonnet-4-20250514', 'Claude Sonnet 4', 'claude-4', false, true, true, 200000, 16384, 3.0000, 15.0000, 0.3000, 'approved'),
  ('anthropic', 'claude-3-5-sonnet-20241022', 'Claude 3.5 Sonnet', 'claude-3.5', false, true, true, 200000, 16384, 3.0000, 15.0000, 0.3000, 'approved'),
