-- ----------------------------------------------------------------------------
-- RAG brick 1a: embedding models as first-class capability-available entities, so
-- resolveRagBackend('rag.embedding') returns a real embedding model (is_embedding) and
-- the brick-1 sweep can enumerate candidates WHERE is_embedding — capability-derived,
-- NOT an allow-list. Each maps to a corpus vector space: v1 → knowledge_embeddings.embedding
-- vector(1024); v2 → embedding_v2 halfvec(2560). Availability is still gated by the
-- provider's is_enabled (operator opt-in) — openai is enabled-by-default, vllm-local is not.
-- The exact v2 model id is the operator-deployed Qwen3-Embedding variant; this is the
-- intended 2560-dim candidate (idempotent DO NOTHING preserves operator edits).
-- ----------------------------------------------------------------------------
INSERT INTO public.ai_model_registry (
  provider, model_id, display_name, model_family,
  is_chat_capable, is_embedding, embedding_dimensions,
  context_window,
  input_price_per_m, output_price_per_m,
  is_available,
  provider_metadata
) VALUES
  -- Instanční embedder v1: model, který svc-model obsluhuje sám (EMBED_ALIAS).
  -- Jméno NESE SIGNÁL: modelDiscovery odvozuje is_embedding z podřetězce v id
  -- (NON_CHAT_MODEL_MARKERS), takže alias bez „embedding" by se zaregistroval
  -- jako CHAT model. Korpus se tímhle modelem embeduje LOKÁLNĚ (v ingestu, MLX;
  -- na serveru llama.cpp) — proto je v1 prostor 1024, ne 1536.
  -- TÝŽ prostor, JINÝ build. Korpus embeduje local-ingest na Apple Silicon
  -- (MLX fp16), server obsluhuje GGUF pod aliasem výš. `insert_knowledge_embedding`
  -- páruje na PŘESNÝ model_id, takže poznámka o sdíleném prostoru u řádku níž
  -- sama nestačila: bez vlastního řádku driver každý vektor z bundlu odmítl
  -- („is not a registered is_embedding model"), a produkce měla 0 embeddingů
  -- při 22 905 hotových vektorech v balíčku (naměřeno 2026-07-31).
  --
  -- Registruje se jako SAMOSTATNÝ řádek, ne přejmenováním: vektor má nést, čím
  -- byl doopravdy spočítán. Vydávat MLX fp16 za vllm build by byla nepravda
  -- v provenienci kvůli průchodu bránou.
  -- is_available = FALSE, a je to POCTIVÉ, ne opatrnost: MLX běží jen na Apple
  -- Silicon, produkční hostitel je x86 Linux — tenhle build tam spustit NELZE. Zápis vektorů
  -- to nepotřebuje (`insert_knowledge_embedding` hledá jen `model_id` +
  -- `is_embedding`), kdežto routování ano (`fn_resolve_embedding_model` chce
  -- `is_available` A enabled providera). Řádek tedy říká „tenhle model znám a
  -- jeho vektory beru", ne „umím ho zavolat".
  ('mlx', 'mlx-community/bge-m3-mlx-fp16', 'BGE-M3 MLX fp16 (RAG v1, 1024, korpusový embedder ingestu, NEspustitelný na serveru)', 'bge-m3',
   false, true, 1024, 8192, 0, 0, false,
   '{"notes": "Korpusový embedder local-ingestu na Apple Silicon. TÝŽ prostor jako bge-m3-embedding (v1, 1024) — jiný build téhož modelu, proto vlastní řádek: insert_knowledge_embedding páruje na přesný model_id a provenience má říkat pravdu o tom, co vektor spočítalo.", "rag_space": "v1"}'::jsonb),
  -- is_available = FALSE, dokud ho discovery neuvidí v živém listingu svc-model
  -- (a nezměří jeho skutečný rozměr — 1024 je tu deklarace k aliasu, který volí instance).
  ('vllm', 'bge-m3-embedding', 'BGE-M3 (RAG v1, 1024, multilingual, instanční)', 'bge-m3',
   false, true, 1024, 8192, 0, 0, false,
   '{"notes": "RAG v1 corpus space — knowledge_embeddings.embedding vector(1024). Self-hosted, OpenAI-compatible /v1/embeddings. Týž model embeduje korpus v local-ingest (mlx-community/bge-m3-mlx-fp16), takže vektory z bundlu a dotaz z platformy sdílí prostor.", "rag_space": "v1"}'::jsonb),
  -- OpenAI zůstává registrované, ale do ŽÁDNÉHO zdejšího prostoru nepatří:
  -- 1536 ≠ 1024 ani 2560, takže fn_resolve_embedding_model vrátí rag_space NULL.
  -- Není to opomenutí — korpus (interní smlouvy) nemá opouštět instanci, a mlčky
  -- zvolený cizí prostor by to udělal bez jediného rozhodnutí.
  ('openai', 'text-embedding-3-small', 'OpenAI text-embedding-3-small (mimo zdejší prostory, 1536)', 'openai-embed',
   false, true, 1536, 8191, 0.02, 0, true,
   '{"notes": "1536 nemapuje na žádný zdejší korpusový prostor (v1=1024, v2=2560) → rag_space NULL. Ponecháno registrované kvůli historickým řádkům a pro instance, které si v1 prostor postaví na 1536.", "rag_space": null}'::jsonb),
  -- is_available = FALSE — týž důvod jako u řádků výš: dostupnost určuje živý listing.
  ('vllm', 'Qwen/Qwen3-Embedding-4B', 'Qwen3-Embedding-4B (RAG v2, 2560, multilingual)', 'qwen-3-embed',
   false, true, 2560, 32768, 0, 0, false,
   '{"notes": "RAG v2 multilingual corpus space — knowledge_embeddings.embedding_v2 halfvec(2560). Self-hosted vLLM, OpenAI-compatible /v1/embeddings, MRL native 2560. Confirm exact deployed model id.", "rag_space": "v2"}'::jsonb)
ON CONFLICT (provider, model_id) DO NOTHING;

-- ----------------------------------------------------------------------------
-- Link every model to its provider registry row so the capability resolvers
-- (aisha_resolve_clow_backend / get_adaptive_model_tiers) can JOIN on
-- provider_registry_id. A model's `provider` is the family key; the registry
-- `slug` is the addressable provider id — they differ for google/vllm. Without
-- this backfill the JOIN's `r.provider = p.slug` arm silently drops Gemini/vLLM
-- models, so a Gemini- or vLLM-only stack would resolve to nothing. Idempotent.
-- ----------------------------------------------------------------------------
UPDATE public.ai_model_registry r
SET provider_registry_id = p.id
FROM public.ai_provider_registry p
WHERE r.provider_registry_id IS NULL
  AND p.slug = CASE r.provider
                 WHEN 'google' THEN 'google-genai'
                 WHEN 'vllm'   THEN 'vllm-local'
                 ELSE r.provider
               END;

