-- ============================================================================
-- Step 7.3 follow-up: enable the graph_context retrieval layer on RAG profiles.
-- Inserts 'graph_context' right after 'kb_retrieval' in priority_order and merges
-- the layer config. Idempotent (skips profiles already wired). Keeps fresh-DB seed
-- in parity with migration *_compose_context_graph_layer.sql.
-- ============================================================================
-- depth/per_seed now live on the typed columns (graph_depth/graph_per_seed), the
-- single SoT read by BOTH compose_context (retrieval) and fn_get_run_graph_context
-- (panel). The graph_context JSONB keeps only layer-presentation config (enabled,
-- max_edges). graph_per_seed=8 preserves the prior retrieval per_seed (was JSONB 8,
-- panel column-default 10 — now unified at 8).
UPDATE public.context_profiles cp
SET
  layers = cp.layers || jsonb_build_object(
    'graph_context',
    jsonb_build_object('enabled', true, 'max_edges', 20)
  ),
  graph_per_seed = 8,
  priority_order = (
    SELECT array_agg(elem ORDER BY ord)
    FROM (
      SELECT t.elem, t.ord::numeric AS ord
      FROM unnest(cp.priority_order) WITH ORDINALITY AS t(elem, ord)
      UNION ALL
      SELECT 'graph_context', t.ord + 0.5
      FROM unnest(cp.priority_order) WITH ORDINALITY AS t(elem, ord)
      WHERE t.elem = 'kb_retrieval'
    ) merged
  )
WHERE COALESCE((cp.layers->'kb_retrieval'->>'enabled')::boolean, false) = true
  AND cp.slug <> 'chat_lightweight'  -- lightweight profile stays lean: no graph layer
  AND NOT (cp.priority_order @> ARRAY['graph_context']);

-- Per-profile graph reasoning budget on the typed column. evidence_strict runs
-- deep/deliberative retrieval → deeper multi-hop traversal than the default 2.
-- Idempotent; honored identically by compose_context and the explainability panel.
UPDATE public.context_profiles SET graph_depth = 3 WHERE slug = 'evidence_strict';


