-- File: core/38_anthropic_operating_principles.sql
-- Lines: 172
-- ==============================================================================
-- ==============================================================================
-- Anthropic Operating Principles — governed expert_rules (core layer)
-- ==============================================================================
-- odysseus impl/16: AISHA "knows and enforces" the Anthropic operating
-- principles by carrying them through her OWN governance path — expert_rules →
-- compose_context ruleset layer + CLAUDE.md overlay (generate-ide-instructions)
-- → knowledge_attribution. A rule without technical enforcement is just text,
-- so every rule's ai_instructions names its enforcement point (G4 gate,
-- impl 01 toolsAllowlist wire, impl 03 budget/compaction, parity package,
-- 05A SSRF, agent-runner permission gates).
--
-- SOURCE ONBOARDING CONTRACT classification (docs/enterprise/
-- SOURCE_ONBOARDING_CONTRACT.md — mandatory 4-dim classification):
--   source_type       = external            (Anthropic published guidance)
--   data_sensitivity  = public              (public engineering practices)
--   retention_class   = long_term           (operating doctrine)
--   legal_basis       = legitimate_interest (operational governance)
-- The classification is mirrored in ai_context_tags on every rule so the
-- retrieval layer and attribution can filter on it.
--
-- Idempotent: ON CONFLICT (slug) DO UPDATE (rules are platform doctrine — a
-- re-seed refreshes the directive text). Skips gracefully when the partner
-- bootstrap has not run yet (author_partner_id is NOT NULL by schema);
-- re-run the seed after onboarding to load the principles.
-- Conformance: src/tests/gates/anthropic-principles-conformance.gate.test.ts
-- ==============================================================================

DO $$
DECLARE
  v_partner_id uuid;
BEGIN
  SELECT id INTO v_partner_id FROM partner_profiles ORDER BY created_at LIMIT 1;
  IF v_partner_id IS NULL THEN
    RAISE NOTICE 'No partner_profiles found — skipping Anthropic operating principles seed (re-run after partner bootstrap).';
    RETURN;
  END IF;

  -- 1. Evals are load-bearing: no model migration without a green eval.
  INSERT INTO expert_rules (
    slug, title, summary, body_markdown, category,
    author_partner_id, visibility,
    ai_instructions, ai_context_tags, status, is_verified, version, published_at
  ) VALUES (
    'anthropic-eval-before-model-migration',
    'Eval before model migration',
    'Changing the operative default model requires a passing eval; without a green eval the default does not change.',
    E'# Eval before model migration\n\nEvals are load-bearing: a model swap without an eval is a regression waiting in production. Before activating a different default model:\n1. Run the benchmark harness (`benchmarkRunner.benchmarkModels` → `record_model_benchmark`) for the relevant task kinds.\n2. The candidate must reach `overall_score >= system_config[''ai_runtime''].eval_min_overall_score` and eval_status tested/approved.\n3. Only then activate. Missing eval result = FAIL (fail-closed), never a silent pass.',
    'testing_strategy'::expert_rule_category,
    v_partner_id, 'public',
    E'RULE: A change of the default/active model REQUIRES a green eval. Enforcement: set_active_ai_model_admin eval-before-migration gate (G4) blocks activation without eval_status tested/approved + ai_model_benchmarks overall_score >= ai_runtime.eval_min_overall_score. Never bypass by editing the registry directly; run the benchmark harness first.',
    ARRAY['anthropic-principles','governance','evals','source_type:external','data_sensitivity:public','retention_class:long_term','legal_basis:legitimate_interest'],
    'published', true, 1, now()
  ) ON CONFLICT (slug) DO UPDATE SET
    ai_instructions = EXCLUDED.ai_instructions,
    ai_context_tags = EXCLUDED.ai_context_tags,
    body_markdown = EXCLUDED.body_markdown,
    status = 'published',
    updated_at = now();

  -- 2. Countermeasure stack before a model downgrade.
  INSERT INTO expert_rules (
    slug, title, summary, body_markdown, category,
    author_partner_id, visibility,
    ai_instructions, ai_context_tags, status, is_verified, version, published_at
  ) VALUES (
    'anthropic-countermeasure-before-downgrade',
    'Countermeasures before downgrade',
    'Exhaust prompt caching, streaming, purpose routing and effort tuning before proposing a cheaper/weaker model.',
    E'# Countermeasures before downgrade\n\nWhen cost or latency pressure appears, the order is:\n1. **Prompt caching** (stable prefix + cache_control) — up to −90 % on cached input.\n2. **Streaming** — perceived latency, avoids timeouts.\n3. **Purpose routing** (`aisha_resolve_clow_backend`) — cheaper model only where the task kind allows it.\n4. **Effort/thinking tuning** — reasoning budget per purpose.\nOnly after these are exhausted may a downgrade of the default model be proposed — and then the eval-before-migration rule applies.',
    'performance_optimization'::expert_rule_category,
    v_partner_id, 'public',
    E'RULE: Before recommending a cheaper model, verify the countermeasure stack was applied: (a) prompt caching enabled for Anthropic-family calls (prepareAnthropicBody cache_control), (b) streaming for long outputs, (c) purpose-based routing via aisha_resolve_clow_backend, (d) reasoningEffort per purpose. Cost optimization = data (registry cached_input_price_per_m), not gut feeling.',
    ARRAY['anthropic-principles','cost','caching','streaming','routing','source_type:external','data_sensitivity:public','retention_class:long_term','legal_basis:legitimate_interest'],
    'published', true, 1, now()
  ) ON CONFLICT (slug) DO UPDATE SET
    ai_instructions = EXCLUDED.ai_instructions,
    ai_context_tags = EXCLUDED.ai_context_tags,
    body_markdown = EXCLUDED.body_markdown,
    status = 'published',
    updated_at = now();

  -- 3. Diagnose before swapping the model.
  INSERT INTO expert_rules (
    slug, title, summary, body_markdown, category,
    author_partner_id, visibility,
    ai_instructions, ai_context_tags, status, is_verified, version, published_at
  ) VALUES (
    'anthropic-diagnose-before-model-swap',
    'Diagnose before model swap',
    'On "the AI is not working": inspect the system prompt and recent failures before changing the model.',
    E'# Diagnose before model swap\n\n"The AI is not working" is a diagnostic trigger, not a migration trigger. Before proposing a different model:\n1. Read the actual system prompt / composed context of the failing runs.\n2. Review the last ~10 failures (ai_runs / trace events / Langfuse) for the real failure mode.\n3. Classify: prompt bug, context overflow, tool failure, retrieval miss — most regressions are NOT the model.\nOnly with a diagnosis in hand may a model change be proposed (and then eval-before-migration applies).',
    'ai_prompt_engineering'::expert_rule_category,
    v_partner_id, 'public',
    E'RULE: When a user reports degraded AI behavior, FIRST request/inspect the effective system prompt and the last ~10 failed runs (ai_runs, ai_trace_events, Langfuse) and name the failure mode. NEVER propose a model swap as the first remediation. A swap proposal must cite the diagnosis + pass the eval gate.',
    ARRAY['anthropic-principles','diagnostics','observability','source_type:external','data_sensitivity:public','retention_class:long_term','legal_basis:legitimate_interest'],
    'published', true, 1, now()
  ) ON CONFLICT (slug) DO UPDATE SET
    ai_instructions = EXCLUDED.ai_instructions,
    ai_context_tags = EXCLUDED.ai_context_tags,
    body_markdown = EXCLUDED.body_markdown,
    status = 'published',
    updated_at = now();

  -- 4. Context is a finite resource.
  INSERT INTO expert_rules (
    slug, title, summary, body_markdown, category,
    author_partner_id, visibility,
    ai_instructions, ai_context_tags, status, is_verified, version, published_at
  ) VALUES (
    'anthropic-context-as-finite-resource',
    'Context is a finite resource',
    'Surface tools and context progressively; compact above threshold; never ship everything at once.',
    E'# Context is a finite resource\n\nEvery token in the window competes with the answer:\n1. **Progressive tool disclosure** — send the tools the routed task needs (route-plan toolsAllowlist), not the full catalog.\n2. **Budgeted input** — respect the model context_window with headroom (ai_runtime.context_budget_headroom; 0.7 because chars/4 underestimates).\n3. **Compaction over truncation** — above compact_threshold summarize old turns (chat.history_compaction purpose), keep the recent tail verbatim.\n4. Long agent runs compact on the orchestrator node boundary, not just chat history.',
    'ai_prompt_engineering'::expert_rule_category,
    v_partner_id, 'public',
    E'RULE: Treat the context window as budgeted: apply route-plan toolsAllowlist narrowing (impl 01), enforce computeInputBudget with ai_runtime.context_budget_headroom, and compact history above ai_runtime.compact_threshold via the governed chat.history_compaction purpose. NULL context_window → parity behavior (no aggressive trimming).',
    ARRAY['anthropic-principles','context','compaction','tool-disclosure','source_type:external','data_sensitivity:public','retention_class:long_term','legal_basis:legitimate_interest'],
    'published', true, 1, now()
  ) ON CONFLICT (slug) DO UPDATE SET
    ai_instructions = EXCLUDED.ai_instructions,
    ai_context_tags = EXCLUDED.ai_context_tags,
    body_markdown = EXCLUDED.body_markdown,
    status = 'published',
    updated_at = now();

  -- 5. Safety as architecture: destructive actions pass a permission gate.
  INSERT INTO expert_rules (
    slug, title, summary, body_markdown, category,
    author_partner_id, visibility,
    ai_instructions, ai_context_tags, status, is_verified, version, published_at
  ) VALUES (
    'anthropic-safety-hook-on-destructive',
    'Safety hook on destructive actions',
    'Destructive tool actions must pass a permission gate/hook; outbound fetches go through the SSRF guard.',
    E'# Safety as architecture\n\nSafety is structural, not a prompt suggestion:\n1. Destructive tool actions (writes, deletes, deployments, spend) pass an explicit permission gate (agent-runner approval_required / permission modes).\n2. Every LLM-driven outbound fetch goes through the SSRF guard (`createSsrfGuard().safeFetch`) — no bare fetch in untrusted paths (static defense rule aisha-raw-fetch-outside-ssrf-guard).\n3. Retrieved external content is fenced as untrusted data at the prompt boundary before it reaches the model.',
    'security_practice'::expert_rule_category,
    v_partner_id, 'public',
    E'RULE: Never execute a destructive tool action without the permission gate (agent_runs.approval_required / runner permission mode). All web/untrusted fetches MUST use @aisha/security createSsrfGuard().safeFetch (enforced by static defense rule aisha-raw-fetch-outside-ssrf-guard). KB/memory/web content is wrapped as untrusted at the prompt boundary.',
    ARRAY['anthropic-principles','safety','ssrf','permission-gates','source_type:external','data_sensitivity:public','retention_class:long_term','legal_basis:legitimate_interest'],
    'published', true, 1, now()
  ) ON CONFLICT (slug) DO UPDATE SET
    ai_instructions = EXCLUDED.ai_instructions,
    ai_context_tags = EXCLUDED.ai_context_tags,
    body_markdown = EXCLUDED.body_markdown,
    status = 'published',
    updated_at = now();

  -- 6. Typed output for machine-consumed results.
  INSERT INTO expert_rules (
    slug, title, summary, body_markdown, category,
    author_partner_id, visibility,
    ai_instructions, ai_context_tags, status, is_verified, version, published_at
  ) VALUES (
    'anthropic-typed-output-for-pipelines',
    'Typed output for pipelines',
    'Where a system consumes the output, demand structured output (schema/jsonMode) — never parse prose.',
    E'# Typed output for pipelines\n\nWhen the consumer of an LLM output is code (judges, extractors, safety scans, routers):\n1. Request structured output — jsonMode at minimum, schema-grammar (output_config) where the provider supports it (provider_metadata.structured_output).\n2. Degrade gracefully: model without structured support → jsonMode → validated parse; never silent prose parsing.\n3. Structured output and citations are mutually exclusive per call — pick per purpose.',
    'api_design'::expert_rule_category,
    v_partner_id, 'public',
    E'RULE: Any LLM call whose output is consumed by code MUST set jsonMode/structured output (ChatRequest.jsonMode; grammar via provider_metadata.structured_output where supported). Parsing free prose in a pipeline is a defect. Structured output must not be combined with citations in one call.',
    ARRAY['anthropic-principles','output','structured-output','source_type:external','data_sensitivity:public','retention_class:long_term','legal_basis:legitimate_interest'],
    'published', true, 1, now()
  ) ON CONFLICT (slug) DO UPDATE SET
    ai_instructions = EXCLUDED.ai_instructions,
    ai_context_tags = EXCLUDED.ai_context_tags,
    body_markdown = EXCLUDED.body_markdown,
    status = 'published',
    updated_at = now();

  RAISE NOTICE 'Anthropic operating principles seeded/refreshed (6 governed expert_rules).';
END $$;


-- File: core/39_agent_operations_gates.sql
-- Lines: 272
-- ==============================================================================
-- ==============================================================================
-- Agent Operations Gates — governed expert_rules (core layer)
-- ==============================================================================
-- Lifecycle gates for autonomous agents: what must be true before work starts,
-- while it runs, and before it is called done. AISHA carries them through her OWN
-- governance path — expert_rules → compose_context ruleset layer + CLAUDE.md
-- overlay (generate-ide-instructions) → knowledge_attribution — exactly like
-- 38_anthropic_operating_principles.sql.
--
-- A rule without technical enforcement is just text, so every rule's
-- ai_instructions names its enforcement point: a .claude/hooks advisory hook, a
-- repo-safety hook, or a gate test. Deleting the hook breaks the conformance gate,
-- not just the doctrine.
--
-- Advisory-only invariant: these hooks WARN. Hard blocking belongs to CI and
-- repo-safety hooks (block-baseline-edit.sh), never to the expert plane — the
-- expert plane has an opinion, not authority.
--
-- PROVENANCE: distilled from operating autonomous coding agents on live projects.
-- Every gate abstracts a real failure mode (unbounded retry loops, abandoned
-- commit backlogs, consent inferred from an adjacent task). The rules are stated
-- as general engineering practice: no third-party content, identifiers, domains,
-- business data or personal data is carried into this seed.
--
-- SOURCE ONBOARDING CONTRACT classification (docs/enterprise/
-- SOURCE_ONBOARDING_CONTRACT.md — mandatory 4-dim classification):
--   source_type       = internal            (our own operating doctrine)
--   data_sensitivity  = public              (general engineering practice)
--   retention_class   = long_term           (operating doctrine)
--   legal_basis       = legitimate_interest (operational governance)
-- The classification is mirrored in ai_context_tags on every rule so the
-- retrieval layer and attribution can filter on it.
--
-- Idempotent: ON CONFLICT (slug) DO UPDATE (rules are platform doctrine — a
-- re-seed refreshes the directive text). Skips gracefully when the partner
-- bootstrap has not run yet (author_partner_id is NOT NULL by schema);
-- re-run the seed after onboarding to load the gates.
-- Conformance: src/tests/gates/agent-operations-gates-conformance.gate.test.ts
-- ==============================================================================

DO $$
DECLARE
  v_partner_id uuid;
BEGIN
  SELECT id INTO v_partner_id FROM partner_profiles ORDER BY created_at LIMIT 1;
  IF v_partner_id IS NULL THEN
    RAISE NOTICE 'No partner_profiles found — skipping agent operations gates seed (re-run after partner bootstrap).';
    RETURN;
  END IF;

  -- 1. Repo State Gate: work that writes starts from a known-clean state.
  INSERT INTO expert_rules (
    slug, title, summary, body_markdown, category,
    author_partner_id, visibility,
    ai_instructions, ai_context_tags, status, is_verified, version, published_at
  ) VALUES (
    'agent-ops-repo-state-gate',
    'Repo State Gate',
    'Work that can write to the repository starts from a known-clean state — an entry check performed at commit time is not an entry check.',
    E'# Repo State Gate\n\nBefore any task that may write to the repository, verify BOTH the git state and the project state:\n\n1. Current branch matches the assignment.\n2. Working tree is clean — no foreign uncommitted changes, no conflicts, no interrupted merge/rebase.\n3. Fast-forward sync with remote. If `git pull --ff-only` fails, STOP — do not edit.\n4. No blocker that takes precedence over the new assignment.\n5. The assignment does not contradict the source of truth on the main branch.\n\n**On mismatch:** stop, describe the blocking condition, change nothing, commit nothing, request a decision. Never bypass with the assumption that it "probably does not matter".\n\n**Why:** work started over a dirty or half-finished tree mixes foreign changes with your own. Untangling that is manual and expensive.',
    'devops_pipeline'::expert_rule_category,
    v_partner_id, 'public',
    E'RULE: Before a write-side git command (commit/push/merge/rebase/cherry-pick), the repo must be in a known-clean state: no interrupted merge/rebase/cherry-pick, no unmerged paths, not detached HEAD, not behind upstream. Enforcement: .claude/hooks/aisha-advise-repo-state.sh (PreToolUse Bash) warns on each of these; .husky/pre-push runs the full CI gate before the push lands. On mismatch STOP and request a decision — never proceed on the assumption it does not matter.',
    ARRAY['agent-operations','governance','git','repo-state','entry-gate','source_type:internal','data_sensitivity:public','retention_class:long_term','legal_basis:legitimate_interest'],
    'published', true, 1, now()
  ) ON CONFLICT (slug) DO UPDATE SET
    ai_instructions = EXCLUDED.ai_instructions,
    ai_context_tags = EXCLUDED.ai_context_tags,
    body_markdown = EXCLUDED.body_markdown,
    status = 'published',
    updated_at = now();

  -- 2. Context reuse: do not re-read what has not changed.
  INSERT INTO expert_rules (
    slug, title, summary, body_markdown, category,
    author_partner_id, visibility,
    ai_instructions, ai_context_tags, status, is_verified, version, published_at
  ) VALUES (
    'agent-ops-context-reuse',
    'Context reuse over blind reread',
    'A blind reread of an unchanged large file burns context and credit for zero information gain — first find out what actually changed, or ask a targeted question.',
    E'# Context reuse over blind reread\n\nDo not routinely re-read large documents already read in this session. First establish what actually changed:\n\n```bash\ngit diff --name-only        # what changed at all\ngit log -- <file>           # did this file change?\ngrep -n "<symbol>" <file>   # targeted question instead of the whole file\n```\n\nRead with offset/limit when only a section is needed.\n\n**A full reread IS warranted when:** new thread or context switch, missing context, a detected file change, or genuine doubt about whether a rule is current.\n\n**Why:** re-ingesting an unchanged file costs context window and credit and returns nothing new. Also part of tool fit: a task that does not match this tool''s role should be handed over or split, not forced through.',
    'ai_prompt_engineering'::expert_rule_category,
    v_partner_id, 'public',
    E'RULE: Do not re-read a large file already read in this session and unchanged since. Establish change first (git diff --name-only, git log -- <file>) or ask a targeted question (grep, Read with offset/limit). Full reread only on: new thread/context switch, missing context, detected change, doubt about currency of a rule. Enforcement: .claude/hooks/aisha-advise-context-reuse.sh (PreToolUse Read) fires when the same path is re-read with an unchanged mtime+size and the read is not already targeted; routerCoach in .aisha/dirigent.json tracks the resulting session cost.',
    ARRAY['agent-operations','governance','context-window','cost','tool-fit','source_type:internal','data_sensitivity:public','retention_class:long_term','legal_basis:legitimate_interest'],
    'published', true, 1, now()
  ) ON CONFLICT (slug) DO UPDATE SET
    ai_instructions = EXCLUDED.ai_instructions,
    ai_context_tags = EXCLUDED.ai_context_tags,
    body_markdown = EXCLUDED.body_markdown,
    status = 'published',
    updated_at = now();

  -- 3. Scope adjacency: consent never follows from a neighbouring task.
  INSERT INTO expert_rules (
    slug, title, summary, body_markdown, category,
    author_partner_id, visibility,
    ai_instructions, ai_context_tags, status, is_verified, version, published_at
  ) VALUES (
    'agent-ops-scope-adjacency',
    'Adjacency is not consent',
    'A high-blast-radius action requires its own explicit approval — it can never be inferred from an adjacent or generally-worded task.',
    E'# Adjacency is not consent\n\nAn ambiguous natural-language instruction gets expanded into its widest reading. For a high-blast target that reading reaches users before a reviewer does.\n\n**Consent NEVER follows from context for:**\n\n- navigation / routing visible to users,\n- destructive DML or migrations over live data,\n- visibility changes (public/hidden, publish, feature flag),\n- rotating or changing secrets,\n- deploy / redeploy / service restart,\n- anything an end user sees before a reviewer does.\n\nCreating an entity, a mutation, or the existence of a URL does **not** by itself imply consent to expose or wire it up.\n\n**If the action seems correct and follows logically:** raise it as a SEPARATE proposal and stop for explicit confirmation. Never perform it as part of another approved change.',
    'project_management'::expert_rule_category,
    v_partner_id, 'public',
    E'RULE: Never infer approval for a high-blast-radius action (navigation/routing, DML over live data, visibility/feature flags, secrets, deploy) from an adjacent or generally-worded task. Raise it as a separate proposal and stop for explicit confirmation. Enforcement: .claude/hooks/aisha-advise-scope-adjacency.sh (PreToolUse Edit|Write|MultiEdit) detects these targets by path and by DML content in migrations and warns that consent must be asked for separately, not derived.',
    ARRAY['agent-operations','governance','scope','approval','blast-radius','source_type:internal','data_sensitivity:public','retention_class:long_term','legal_basis:legitimate_interest'],
    'published', true, 1, now()
  ) ON CONFLICT (slug) DO UPDATE SET
    ai_instructions = EXCLUDED.ai_instructions,
    ai_context_tags = EXCLUDED.ai_context_tags,
    body_markdown = EXCLUDED.body_markdown,
    status = 'published',
    updated_at = now();

  -- 4. Bounded self-correction: the fix loop has a hard ceiling.
  INSERT INTO expert_rules (
    slug, title, summary, body_markdown, category,
    author_partner_id, visibility,
    ai_instructions, ai_context_tags, status, is_verified, version, published_at
  ) VALUES (
    'agent-ops-bounded-self-correction',
    'Bounded self-correction loop',
    'Audit your own output and correct it — but inside a loop with a hard ceiling: max 3 passes, and an identical repeated error stops immediately.',
    E'# Bounded self-correction loop\n\nAfter producing output with verifiable criteria, audit it and correct — inside a bounded loop.\n\n```text\n1. Produce / modify output.\n2. Audit. State the result: AUDIT PASSED / AUDIT FAILED.\n3. PASSED → continue.\n4. FAILED → root-cause analysis → fix (inside scope only) → re-audit.\n```\n\n**Brakes — any one stops the loop immediately:**\n\n- **Attempt ceiling:** max 3 audit passes (= 2 correction attempts).\n- **Repeated-error stop:** if an IDENTICAL error recurs after a fix, stop at once. Do not spend the remaining attempts — an identical error means the causal model is wrong, and another attempt will not fix it, only cost more.\n- **Scope stop:** if the cause lies outside the approved scope, stop and report the blocker. Never fix silently across a scope boundary.\n\n**On a brake:** do NOT commit, do NOT deploy. Report the last failure, the root-cause analysis, and what you tried. The decision returns to a human.',
    'ai_prompt_engineering'::expert_rule_category,
    v_partner_id, 'public',
    E'RULE: The fix→re-verify loop is bounded: max 3 audit passes (2 correction attempts); an IDENTICAL repeated error stops immediately without spending remaining attempts; a cause outside the approved scope stops and reports a blocker. On any brake do not commit and do not deploy — report the last failure, the cause analysis and what was tried. Enforcement: .claude/hooks/aisha-advise-retry-loop.sh (PreToolUse Bash) hashes each non-read-only command per session and fires from the 3rd verbatim re-run, the observable signature of an unbounded loop.',
    ARRAY['agent-operations','governance','self-correction','retry','autonomy','source_type:internal','data_sensitivity:public','retention_class:long_term','legal_basis:legitimate_interest'],
    'published', true, 1, now()
  ) ON CONFLICT (slug) DO UPDATE SET
    ai_instructions = EXCLUDED.ai_instructions,
    ai_context_tags = EXCLUDED.ai_context_tags,
    body_markdown = EXCLUDED.body_markdown,
    status = 'published',
    updated_at = now();

  -- 5. Mandatory lens: cross-cutting duties fire unasked.
  INSERT INTO expert_rules (
    slug, title, summary, body_markdown, category,
    author_partner_id, visibility,
    ai_instructions, ai_context_tags, status, is_verified, version, published_at
  ) VALUES (
    'agent-ops-mandatory-lens',
    'Mandatory cross-cutting lens',
    'A cross-cutting obligation fires even when the assignment never mentioned it — it must not be silently skipped.',
    E'# Mandatory cross-cutting lens\n\nAn agent optimises for the literal wording of the assignment. Whatever the assignment did not name drops out silently — and the missing translation or validation surfaces in production.\n\n**Mandatory lenses on this platform:**\n\n| Lens | Fires when | Reference |\n|---|---|---|\n| i18n | the task creates or changes user-visible text | i18n standards — all UI text via `t("key")` |\n| Currency / locale | the task touches an amount, format or language | dynamic config, never a hardcoded literal |\n| Security | the task touches input, authorization, logs, secrets | security standards |\n| Tests | the task adds a function, endpoint or hook | testing philosophy |\n\n**Required lens output:**\n\n```text\n<Lens> Gate: APPLIED / NOT APPLICABLE / BLOCKED\nAffected scope:\nCreated / updated / verified:\nOpen issues, or why it could not be safely completed:\n```\n\n`NOT APPLICABLE` only when the task demonstrably does not touch that area.\n\n**A lens does NOT widen the write scope of the task.** Without approved scope for that area, audit and report the state — do not silently write outside scope.',
    'coding_standard'::expert_rule_category,
    v_partner_id, 'public',
    E'RULE: Cross-cutting obligations (i18n, currency/locale, security, tests) apply even when the assignment did not mention them; never silently skip one. Report each as APPLIED / NOT APPLICABLE / BLOCKED — NOT APPLICABLE only when the task demonstrably does not touch that area. A lens never widens the task write scope: without approved scope, audit and report rather than write. Enforcement: .claude/hooks/aisha-advise-i18n.sh (PreToolUse Edit|Write|MultiEdit) flags hardcoded user-visible text unasked; the gate suite in src/tests/gates/ enforces the same duties statically at CI time.',
    ARRAY['agent-operations','governance','i18n','security','cross-cutting','lens','source_type:internal','data_sensitivity:public','retention_class:long_term','legal_basis:legitimate_interest'],
    'published', true, 1, now()
  ) ON CONFLICT (slug) DO UPDATE SET
    ai_instructions = EXCLUDED.ai_instructions,
    ai_context_tags = EXCLUDED.ai_context_tags,
    body_markdown = EXCLUDED.body_markdown,
    status = 'published',
    updated_at = now();

  -- 6. Closure backlog brake: never walk away from a large unresolved backlog.
  INSERT INTO expert_rules (
    slug, title, summary, body_markdown, category,
    author_partner_id, visibility,
    ai_instructions, ai_context_tags, status, is_verified, version, published_at
  ) VALUES (
    'agent-ops-closure-backlog-brake',
    'Post-task closure gate and backlog brake',
    'No task is done until the repository is settled — and once the backlog outgrows the task, STOP rather than bulk-commit blindly.',
    E'# Post-task closure gate and backlog brake\n\n**No task is done until the repository is settled.**\n\n```text\n1. Working tree is clean, OR every remaining file is explicitly classified:\n   commit / ignore / move / keep-with-stated-reason.\n   No anonymous unresolved pile is left behind.\n2. State versus remote (ahead / behind / in-sync) is determined and stated.\n3. No interrupted merge, rebase or conflict.\n```\n\n**Backlog brake:**\n\n```text\nIf the count of unresolved changes (uncommitted + untracked + unpushed) outgrows\nthe expected scope of the task — roughly past ~20 files, or containing files\nUNRELATED to the assignment — STOP and report before doing anything else.\n\nNo blind bulk commit. No push. The ~20 threshold is a catch, not dogma: the point\nis that a large backlog never slips past without a human decision.\n```\n\n**Required output:**\n\n```text\nClosure Gate: CLEAN / RESOLVED / STOP\nWorking tree:\nAhead/behind remote:\nRemaining files and their classification:\nRecommended action (push / pull / none):\nIf STOP: reason and what awaits a decision.\n```\n\n**Why:** a real failure mode — execution tools walking away from a task leaving hundreds of files in commit/push/pull limbo. The cleanup is manual and expensive.',
    'devops_pipeline'::expert_rule_category,
    v_partner_id, 'public',
    E'RULE: A task is not done until the working tree is clean or every remaining file is explicitly classified (commit/ignore/move/keep-with-reason), the ahead/behind state is stated, and no merge/rebase is interrupted. Backlog brake: once unresolved changes outgrow the task scope (~20 files, or files unrelated to the assignment) STOP and report — never a blind bulk commit, never a push. Enforcement: .claude/hooks/aisha-advise-closure-backlog.sh (Stop) counts uncommitted+untracked+unpushed and raises a STOP advisory past the threshold.',
    ARRAY['agent-operations','governance','closure','git','backlog','exit-gate','source_type:internal','data_sensitivity:public','retention_class:long_term','legal_basis:legitimate_interest'],
    'published', true, 1, now()
  ) ON CONFLICT (slug) DO UPDATE SET
    ai_instructions = EXCLUDED.ai_instructions,
    ai_context_tags = EXCLUDED.ai_context_tags,
    body_markdown = EXCLUDED.body_markdown,
    status = 'published',
    updated_at = now();

  -- 7. Impact consistency: new knowledge has exactly one relation to old.
  INSERT INTO expert_rules (
    slug, title, summary, body_markdown, category,
    author_partner_id, visibility,
    ai_instructions, ai_context_tags, status, is_verified, version, published_at
  ) VALUES (
    'agent-ops-impact-consistency',
    'Impact consistency: supersedes, scoped, or conflict',
    'New information stands in exactly one of three relations to what exists — and a conflict must never be filed as done.',
    E'# Impact consistency: supersedes, scoped, or conflict\n\n## New information is not a new file\n\nBefore creating a new document:\n\n```text\n1. Search for an existing document on the same topic / area / problem.\n2. If a living document, registry or policy exists for it → add there, timestamped.\n3. Only if none exists → propose a new file and justify it.\n```\n\nA new file is NOT justified merely because another note appeared on the same topic, the existing file is long, or writing it aside is more convenient.\n\n**No duplicate transcription:** the same finding is not copied in full into several files. Detail lives in one place; the rest reference it.\n\n## The three-way verdict\n\n```text\nSupersedes         → rewrite the older / mark it historical / link forward.\nScoped coexistence → both hold, in different scopes; state explicitly which applies when.\nConflict           → contradiction with no clear precedence → do NOT close as done;\n                     return to decision mode.\n```\n\n## Living document vs snapshot vs baseline\n\n```text\nliving document = continuously updated source of truth → edited in place\nsnapshot        = closed evidence of a state on a date → NEVER rewritten retroactively\nbaseline        = prior state kept for later comparison → NEVER rewritten retroactively\n```\n\nA baseline is never edited to pretend the past state was different. Platform analogue: a generated artifact is fixed at its source and regenerated, never in place — the DB baseline is generated from `aisha/db/sql/` and is never edited directly.\n\n**Why:** without the verdict two truths coexist and nobody knows which holds. A contradiction filed as "done" is worse than one admitted.',
    'documentation_standard'::expert_rule_category,
    v_partner_id, 'public',
    E'RULE: Before creating a new document, check for an existing living document on the same topic and add there instead; never copy the same finding verbatim into several files. Then state the impact verdict — exactly one of Supersedes (rewrite/mark the older), Scoped coexistence (state which applies when), or Conflict (do NOT close as done; return to decision mode). Snapshots and baselines are never rewritten retroactively; generated artifacts are fixed at source and regenerated. Enforcement: .claude/hooks/aisha-advise-impact-consistency.sh (PreToolUse Write) fires when a new .md is created beside topically-near siblings; .claude/hooks/block-baseline-edit.sh hard-blocks direct edits to the generated DB baseline.',
    ARRAY['agent-operations','governance','documentation','knowledge','baseline','source-of-truth','source_type:internal','data_sensitivity:public','retention_class:long_term','legal_basis:legitimate_interest'],
    'published', true, 1, now()
  ) ON CONFLICT (slug) DO UPDATE SET
    ai_instructions = EXCLUDED.ai_instructions,
    ai_context_tags = EXCLUDED.ai_context_tags,
    body_markdown = EXCLUDED.body_markdown,
    status = 'published',
    updated_at = now();

  -- 8. UNCLEAR is a first-class state: never guess, escalate.
  INSERT INTO expert_rules (
    slug, title, summary, body_markdown, category,
    author_partner_id, visibility,
    ai_instructions, ai_context_tags, status, is_verified, version, published_at
  ) VALUES (
    'agent-ops-unclear-escalation',
    'UNCLEAR is a first-class state',
    'A decision gate returns three states, not two — an agent that cannot decide escalates instead of guessing.',
    E'# UNCLEAR is a first-class state\n\n```text\nNO      – does not apply; continue.\nYES     – applies; run its procedure.\nUNCLEAR – I cannot decide → ESCALATE to a human.\n```\n\nNeither `YES` nor `UNCLEAR` may remain a standalone note without action. One of these must follow: a concrete step, a prompt for the next tool, a plan, or an EXPLICIT blocker with a reason. If the action is deferred, say why.\n\n**Also:** deliver a final output, not a draft with a promise to polish later. If two variants are genuinely equivalent, or the choice depends on a decision outside your remit, state the difference and request the decision. **Uncertainty must not be masked by stylistic confidence.**\n\n**Why:** a two-state gate forces the agent to guess when it does not know — and it guesses toward "continue". UNCLEAR gives permission to admit uncertainty rather than hide it.',
    'ai_prompt_engineering'::expert_rule_category,
    v_partner_id, 'public',
    E'RULE: Decision gates return three states: NO (continue), YES (run the procedure), UNCLEAR (cannot decide → escalate to a human). Never guess toward "continue". YES and UNCLEAR must be followed by a concrete step, a plan, or an explicit blocker with a reason — never left as a standalone note. Deliver a final output, not a draft with a promise; never mask uncertainty with stylistic confidence. Enforcement: .claude/hooks/aisha-advise-open-state.sh (Stop) fires at closure when work was done, requiring disclosure of what is verified, what is open, and what could not be decided.',
    ARRAY['agent-operations','governance','escalation','uncertainty','autonomy','source_type:internal','data_sensitivity:public','retention_class:long_term','legal_basis:legitimate_interest'],
    'published', true, 1, now()
  ) ON CONFLICT (slug) DO UPDATE SET
    ai_instructions = EXCLUDED.ai_instructions,
    ai_context_tags = EXCLUDED.ai_context_tags,
    body_markdown = EXCLUDED.body_markdown,
    status = 'published',
    updated_at = now();

  -- 9. Stop ends actions, not the duty to disclose.
  INSERT INTO expert_rules (
    slug, title, summary, body_markdown, category,
    author_partner_id, visibility,
    ai_instructions, ai_context_tags, status, is_verified, version, published_at
  ) VALUES (
    'agent-ops-stop-is-not-closure',
    'Stop ends actions, not disclosure',
    'An instruction to stop ends operations — it does not end the duty to disclose that something remains open.',
    E'# Stop ends actions, not disclosure\n\nWhen "do nothing" / "stop" / "leave it" is given, it ends ACTIONS. It does **not** mean:\n\n```text\n- cancelling the duty to state that an open point remains,\n- pretending a conclusion is closed when nothing was decided,\n- replacing a required check with a general summary.\n```\n\n**Why:** the most dangerous state is an open problem everyone believes is closed. Silence after "stop" reads as "done".\n\nAt closure, say plainly:\n\n```text\n- what is verified (and by what evidence — not "it should work"),\n- what remains open,\n- what you could not decide, and who decides it.\n```',
    'project_management'::expert_rule_category,
    v_partner_id, 'public',
    E'RULE: An instruction to stop ends actions, not the duty to disclose open state. Never present an undecided conclusion as closed, and never replace a required check with a general summary because writing it up is inconvenient. At closure state what is verified (with evidence, not "it should work"), what remains open, and what could not be decided and by whom. Enforcement: .claude/hooks/aisha-advise-open-state.sh (Stop) fires when the tree is dirty at closure and requires the disclosure triple.',
    ARRAY['agent-operations','governance','closure','disclosure','honesty','source_type:internal','data_sensitivity:public','retention_class:long_term','legal_basis:legitimate_interest'],
    'published', true, 1, now()
  ) ON CONFLICT (slug) DO UPDATE SET
    ai_instructions = EXCLUDED.ai_instructions,
    ai_context_tags = EXCLUDED.ai_context_tags,
    body_markdown = EXCLUDED.body_markdown,
    status = 'published',
    updated_at = now();

  -- 10. No placeholders in runnable commands.
  INSERT INTO expert_rules (
    slug, title, summary, body_markdown, category,
    author_partner_id, visibility,
    ai_instructions, ai_context_tags, status, is_verified, version, published_at
  ) VALUES (
    'agent-ops-no-placeholder-commands',
    'No placeholders in runnable commands',
    'A command is either directly runnable or it is not phrased as a command — a placeholder run verbatim either fails or hits the wrong target.',
    E'# No placeholders in runnable commands\n\n```bash\n# FORBIDDEN — it gets run verbatim, or it wastes the reader''s time\npsql -h <DB_HOST> -U <USER> -d <DB>\ncurl -H "Authorization: Bearer YOUR_API_KEY" https://api.example.com\n\n# CORRECT — determine the real value first, or do not phrase it as a command\n```\n\nIf the value is unknown:\n\n```text\n- verify it first (grep the config, `git config`, query the API),\n- or request it,\n- a command handed over is either directly runnable,\n- or it is not phrased as a command.\n```\n\nIf you need to show the shape of a command, label it as an example, not as a step to execute.\n\n**Why:** a placeholder executed literally either fails outright or — worse — hits the wrong target.',
    'coding_standard'::expert_rule_category,
    v_partner_id, 'public',
    E'RULE: Never hand over a runnable command containing placeholder tokens (<DB_HOST>, {{TOKEN}}, YOUR_API_KEY, <your-token>). If a value is unknown, verify it first or request it; a command is either directly runnable or is not phrased as a command. Show shapes only when explicitly labelled as an example. Enforcement: .claude/hooks/aisha-advise-placeholder-cmd.sh (PreToolUse Bash) detects angle, template, sample-value and doc-style placeholders in the command before it runs.',
    ARRAY['agent-operations','governance','commands','handover','fail-loud','source_type:internal','data_sensitivity:public','retention_class:long_term','legal_basis:legitimate_interest'],
    'published', true, 1, now()
  ) ON CONFLICT (slug) DO UPDATE SET
    ai_instructions = EXCLUDED.ai_instructions,
    ai_context_tags = EXCLUDED.ai_context_tags,
    body_markdown = EXCLUDED.body_markdown,
    status = 'published',
    updated_at = now();

END $$;


-- File: core/39_coolify_routing_doctrine.sql
-- Lines: 95
-- ==============================================================================
-- ==============================================================================
-- Coolify routing doctrine — governed expert_rules (core layer)
-- ==============================================================================
-- Deployment doctrine belongs in the governance path (expert_rules →
-- compose_context ruleset layer + CLAUDE.md overlay via
-- generate-ide-instructions), NOT hand-written into CLAUDE.md, which is
-- generated. A rule without technical enforcement is just text, so each rule's
-- ai_instructions names the gate that enforces it.
--
-- WHY THIS RULE EXISTS (measured 2026-07-18):
-- Coolify rewrites `$` -> `$$` in container label VALUES, and only there. Docker
-- then reads `$$` as an escaped literal `$`, so `Host(`${VAR}`)` reaches Traefik
-- as a request for a host literally named "${VAR}". It matches nothing, forever,
-- with no error and no log line. Every other YAML site is untouched:
--   environment: 751 uses OK | command/healthcheck: 181 OK | networks: 4 OK
--   labels: 56 DEAD
-- 1036 uses, 980 work, 56 die, identical syntax. That asymmetry is the trap —
-- you learn "we write ${VAR}" from 980 working examples and apply it in a label.
--
-- Three conflicting instructions had accumulated: docs/deploy/TRAEFIK_LABELS.md
-- said "use a literal hostname"; coolify-traefik-label-substitution.gate.test.ts
-- said "use bare ${VAR}"; only a later section of that same gate stated the
-- correct rule, and enforced it on one compose file. Commit 3fd92028 followed the
-- bad advice and produced another dead label; 7ed24a86 designed a tri-host
-- Keycloak router on top of dead labels, so that design never took effect.
--
-- SOURCE ONBOARDING CONTRACT classification (docs/enterprise/
-- SOURCE_ONBOARDING_CONTRACT.md — mandatory 4-dim classification):
--   source_type       = internal            (own measured deployment behaviour)
--   data_sensitivity  = public              (engineering practice, no tenant data)
--   retention_class   = long_term           (deployment doctrine)
--   legal_basis       = legitimate_interest (operational governance)
--
-- Idempotent: ON CONFLICT (slug) DO UPDATE. Skips gracefully when the partner
-- bootstrap has not run yet (author_partner_id is NOT NULL by schema).
-- Enforcement: src/tests/gates/coolify-traefik-label-substitution.gate.test.ts
--              src/tests/gates/traefik-host-coverage.gate.test.ts
-- ==============================================================================

DO $seed$
DECLARE
  v_partner_id uuid;
BEGIN
  SELECT id INTO v_partner_id FROM partner_profiles ORDER BY created_at LIMIT 1;
  IF v_partner_id IS NULL THEN
    RAISE NOTICE 'No partner_profiles found — skipping Coolify routing doctrine seed (re-run after partner bootstrap).';
    RETURN;
  END IF;

  -- 1. No hostname in a Traefik label — routing is declared in docker_compose_domains.
  INSERT INTO expert_rules (
    slug, title, summary, body_markdown, category,
    author_partner_id, visibility,
    ai_instructions, ai_context_tags, status, is_verified, version, published_at
  ) VALUES (
    'coolify-no-hostname-in-traefik-label',
    'No hostname in a Traefik label',
    'Coolify escapes $ to $$ in label values, so a Traefik Host() rule can carry neither ${VAR} (never matches) nor a literal (bakes a deployment into the platform contract). Declare public routing in docker_compose_domains.',
    E'# No hostname in a Traefik label\n\nA Traefik label must never contain a hostname — not `${VAR}`, not a literal. Public routing is declared ONLY in Coolify `docker_compose_domains`, via `scripts/coolify-domain-doctor.mjs`.\n\n## Why `${VAR}` is dead\n\nCoolify rewrites `$` to `$$` when rendering a container''s label VALUES, and only there. Docker reads `$$` as an escaped literal `$`, so the variable never expands and Traefik searches for a host literally named `${VAR}`. It matches nothing, forever, with **no error and no log line**.\n\n## Why a literal is banned\n\nIt does match — and bakes a deployment hostname into the platform contract (the public TLD is a DEFAULT, not a constant), and activates an un-namespaced `priority=99999` router on a Traefik shared across forks, out-ranking Coolify''s own correct generated router.\n\n## Trust the SITE, not the pattern\n\nMeasured 2026-07-18: `environment:` 751 uses expand, `command:`/`healthcheck:` 181 expand, `networks:` 4 expand, `labels:` 56 die. 1036 uses, 980 work, 56 dead — identical syntax. You learn "we write `${VAR}`" from 980 working examples and apply it in a label.\n\n## What IS legal in a label\n\nHost-less matchers — they carry no `$` and no deployment identity, and Coolify''s generator cannot express them:\n\n```yaml\n- "traefik.http.routers.netbird-grpc.rule=PathPrefix(`/management.ManagementService`)"\n- "traefik.http.services.netbird-management.loadbalancer.server.scheme=h2c"\n```\n\n## Diagnosing\n\nA dead label produces no error, just no router: Traefik answers 404 with NO `server:` header, identical to a nonsense subdomain. Traefik''s API is not exposed — read the rendered labels with `docker inspect` instead.',
    'devops_pipeline'::expert_rule_category,
    v_partner_id, 'public',
    E'RULE: Never write a hostname into a traefik.* label — neither Host(`${VAR}`) (Coolify escapes $ to $$; the router never matches) nor Host(`literal`) (bakes a deployment into the platform contract and activates an un-namespaced priority=99999 router on a shared proxy). Declare the route in Coolify docker_compose_domains via scripts/coolify-domain-doctor.mjs. Host-less PathPrefix/Path/Method matchers remain legal. NOTE the asymmetry: ${VAR} is correct and required in environment:/command:/networks:/volume name: — the escape applies to label VALUES only. Enforcement: coolify-traefik-label-substitution.gate.test.ts (label form), traefik-host-coverage.gate.test.ts (topology coverage). Do NOT "fix" a flagged label by switching ${VAR:-x} to bare ${VAR}; both are dead.',
    ARRAY['deployment','coolify','traefik','routing','source_type:internal','data_sensitivity:public','retention_class:long_term','legal_basis:legitimate_interest'],
    'published', true, 1, now()
  ) ON CONFLICT (slug) DO UPDATE SET
    ai_instructions = EXCLUDED.ai_instructions,
    ai_context_tags = EXCLUDED.ai_context_tags,
    body_markdown = EXCLUDED.body_markdown,
    status = 'published',
    updated_at = now();

  -- 2. Same substitution mechanism, stated as the general lesson: the SITE decides.
  INSERT INTO expert_rules (
    slug, title, summary, body_markdown, category,
    author_partner_id, visibility,
    ai_instructions, ai_context_tags, status, is_verified, version, published_at
  ) VALUES (
    'compose-substitution-depends-on-site',
    'Compose substitution depends on the YAML site',
    'The same ${VAR} syntax has different fates depending on which YAML block it sits in. Verify the site before assuming a variable expands.',
    E'# Compose substitution depends on the YAML site\n\n`${VAR}` in a compose file is not one mechanism — its fate depends on WHERE it sits, because Coolify post-processes the rendered file:\n\n| site | fate |\n|---|---|\n| `environment:` | expands — correct and required |\n| `command:` / `healthcheck:` | expands — correct |\n| `networks:` / `aliases:` / volume `name:` | expands — correct |\n| `labels:` | **escaped to `$$` — dead** |\n\nNothing in the file marks the difference, and the repo is overwhelmingly consistent in FORM (1036 uses of `${VAR}`), which is precisely why the 56 dead ones survived: consistency taught the wrong lesson.\n\n## How to check, not guess\n\n```bash\ndocker compose -f <file> config          # what docker renders\ndocker inspect <container> --format \x27{{json .Config.Labels}}\x27   # what Coolify actually deployed\n```\n\nIf a rendered value still contains `${`, it did not expand. Two writers for one job (a compose label AND a Coolify-side registration both claiming to route a host) is the shape to look for — one of them is inert.',
    'devops_pipeline'::expert_rule_category,
    v_partner_id, 'public',
    E'RULE: Before assuming ${VAR} expands in a compose file, check the YAML site. environment:/command:/healthcheck:/networks:/volume name: expand normally; labels: are $-escaped by Coolify and never expand. Verify with `docker compose config` (docker''s view) and `docker inspect` (what Coolify deployed) rather than reasoning from neighbouring examples — the repo uses ${VAR} in 1036 places and 56 of them are inert. When two mechanisms both claim to perform one job (compose label vs Coolify docker_compose_domains), determine which is actually load-bearing before building on either.',
    ARRAY['deployment','coolify','compose','substitution','source_type:internal','data_sensitivity:public','retention_class:long_term','legal_basis:legitimate_interest'],
    'published', true, 1, now()
  ) ON CONFLICT (slug) DO UPDATE SET
    ai_instructions = EXCLUDED.ai_instructions,
    ai_context_tags = EXCLUDED.ai_context_tags,
    body_markdown = EXCLUDED.body_markdown,
    status = 'published',
    updated_at = now();

END $seed$;


-- File: core/40_extension_spine_doctrine.sql
-- Lines: 138
-- ==============================================================================
-- ==============================================================================
-- Extension spine doctrine — governed expert_rules (core layer)
-- ==============================================================================
-- How extension is thought about. Not "which folder does my code go in", but:
-- WHICH EXISTING SPINE DOES THIS RIDE, and does my shape reach the far end of it?
--
-- WHY THESE RULES EXIST (measured 2026-07-26, two collisions in one day):
--
-- (A) A plugin was authored with `"kind": "backend_provider"`. Measured the same
--     day against the SoT:
--       schemas/plugin-manifest.schema.json declares 6 kinds
--         web_tracking · auth_provider · backend_provider
--         automation_node · full_stack · agent
--       aisha/db/sql/functions/ contains 1 materializer
--         materialize_agent_runtime.sql
--     5 of 6 declared kinds have no loader. The manifest validates, the plugin
--     submits, the catalog row appears — and nothing ever materializes into
--     ai_provider_registry, so aisha_resolve_clow_backend can never route to it.
--     It fails by being INERT: no error, no log line, a green-looking artifact
--     that is not connected to anything. (Independently mapped 2026-07-03 in the
--     extension-unification review, main @ 221a2ff5; unchanged 23 days later.)
--
-- (B) Three carriers were built for one domain (vehicle log book: vehicles,
--     drivers, rides, odometer, distance):
--       services/svc-webdispecink   SOAP _getCarLogBook4
--       services/svc-tcars          tc_rides / tc_vehicles / tc_drivers / tc_groups
--       plugins/eurowag-telematics  REST trips / vehicles / drivers
--     Two of them within 24 hours, by the same author, without noticing they were
--     one thing. Each vendor looked like an integration; none of them was.
--
-- Both collisions are ONE mistake: building a new carrier instead of naming the
-- existing spine. The spine already exists in both cases and is proven by a
-- working reference — manifest -> materializer -> registry row -> resolver
-- (agents), and (source, observation, identity signals) -> twin
-- (production_sensor_readings.source already enumerates homeassistant | manual |
-- plc | lims | iot_gateway | scada).
--
-- SOURCE ONBOARDING CONTRACT classification (docs/enterprise/
-- SOURCE_ONBOARDING_CONTRACT.md — mandatory 4-dim classification):
--   source_type       = internal            (own measured engineering behaviour)
--   data_sensitivity  = public              (engineering practice, no tenant data)
--   retention_class   = long_term           (architectural doctrine)
--   legal_basis       = legitimate_interest (operational governance)
--
-- Idempotent: ON CONFLICT (slug) DO UPDATE. Skips gracefully when the partner
-- bootstrap has not run yet (author_partner_id is NOT NULL by schema).
--
-- ENFORCEMENT STATUS (updated 2026-07-26 evening — owner decided: "doplnit"):
--   rule 1 ENFORCED: src/tests/gates/plugin-kind-has-materializer.gate.test.ts
--     (schema enum ≡ DB enum ≡ dispatcher branches ≡ materialize_* files ≡
--      spec columns; call sites must use the dispatcher) + the dispatcher's
--      ELSE RAISE as its runtime twin. Materializers exist for ALL kinds now.
--   rule 2/3 still ai_instructions-only; owed:
--     src/tests/gates/no-per-vendor-carrier.gate.test.ts (needs the tcars
--     retirement decision first — the gate would flag the existing tc_* family)
-- ==============================================================================

DO $seed$
DECLARE
  v_partner_id uuid;
BEGIN
  SELECT id INTO v_partner_id FROM partner_profiles ORDER BY created_at LIMIT 1;
  IF v_partner_id IS NULL THEN
    RAISE NOTICE 'No partner_profiles found — skipping extension spine doctrine seed (re-run after partner bootstrap).';
    RETURN;
  END IF;

  -- 1. A declared capability that never materializes is inert, not "pending".
  INSERT INTO expert_rules (
    slug, title, summary, body_markdown, category,
    author_partner_id, visibility,
    ai_instructions, ai_context_tags, status, is_verified, version, published_at
  ) VALUES (
    'declared-extension-must-reach-the-resolver',
    'A declared extension must reach the resolver',
    'A manifest kind with no materializer produces a catalog row and nothing else — it validates, submits and looks green while being unreachable. Before authoring any extension, verify the kind has a materializer that yields a resolver-visible registry row.',
    E'# A declared extension must reach the resolver\n\nThe stack can be extended eight ways. Only some of them carry a declared capability all the way into the runtime resolver. **Declaring is not wiring.**\n\n## The one correct path (the reference)\n\n```\nmanifest capabilities  ->  materialize_*(...)  ->  registry row  ->  resolver\n   plugin-manifest          in the approval txn     agent_catalog /     derive_clow_needs\n   .schema.json                                     ai_provider_registry -> fn_admit_clow\n                                                    ai_runtime_registry  -> aisha_resolve_clow_backend\n```\n\nNothing about this is agent-specific. It is the contract every surface should share, and it is already locked by the gates `admission-composes-registries` and `runtime-availability-no-allowlist`: a verdict must derive from registries + policy, never from an allow-list.\n\n## The measured gap (2026-07-26)\n\n| declared kind | materializer | reaches resolver |\n|---|---|---|\n| `agent` | `materialize_agent_runtime` | yes |\n| `backend_provider` | — | **no** |\n| `automation_node` | — | **no** |\n| `auth_provider` | — | **no** |\n| `web_tracking` | — | **no** |\n| `full_stack` | — | **no** |\n\nSix kinds in `schemas/plugin-manifest.schema.json`, one materializer in `aisha/db/sql/functions/`.\n\n## Why this is a trap and not a TODO\n\nA dead kind does not reject you. The manifest passes schema validation, `submit_plugin` accepts it, the state machine advances, a `plugin_catalog` row exists. Every signal you normally read says success. The absence is at the far end, where nothing calls you — and nothing logs that nothing called you.\n\nThis is the same failure shape as a Traefik label that never matches: **a green artifact wired to nothing** (see `coolify-no-hostname-in-traefik-label`).\n\n## What to do instead\n\nBefore authoring an extension of kind `K`:\n\n```bash\nls aisha/db/sql/functions/ | grep materialize   # is K wired at all?\n```\n\n- **Materializer exists** — author the manifest, and assert the registry row appears after approval.\n- **No materializer** — you have two honest options: add `materialize_K` following `materialize_agent_runtime` as the template (called from the same approval gate, in the same transaction), or do not use the plugin surface for this. Do NOT author a manifest against a dead kind and treat the missing wiring as someone else''s later problem.',
    'architecture_pattern'::expert_rule_category,
    v_partner_id, 'public',
    E'RULE: Before authoring any plugin/extension manifest, verify the declared kind has a materializer: `ls aisha/db/sql/functions/ | grep materialize`. Measured 2026-07-26: schemas/plugin-manifest.schema.json declares 6 kinds (web_tracking, auth_provider, backend_provider, automation_node, full_stack, agent) and only materialize_agent_runtime exists — so 5 of 6 kinds are INERT. A dead kind does not error: the manifest validates, submit_plugin accepts, a plugin_catalog row appears, and the capability never reaches aisha_resolve_clow_backend. Do not read "it submitted successfully" as "it is wired". If the kind has no materializer, either add materialize_<kind> modelled on materialize_agent_runtime (same approval gate, same transaction, registry row carries the declared caps) or do not use the plugin surface. Never introduce a new manifest format or a parallel loader — the plugin manifest is the single extension contract and already covers all 6 kinds.',
    ARRAY['architecture','extension','plugin','registry','resolver','capability','source_type:internal','data_sensitivity:public','retention_class:long_term','legal_basis:legitimate_interest'],
    'published', false, 1, now()
  ) ON CONFLICT (slug) DO UPDATE SET
    ai_instructions = EXCLUDED.ai_instructions,
    ai_context_tags = EXCLUDED.ai_context_tags,
    body_markdown = EXCLUDED.body_markdown,
    summary = EXCLUDED.summary,
    status = 'published',
    updated_at = now();

  -- 2. External observations ride one shape; the vendor is a value, not a schema.
  INSERT INTO expert_rules (
    slug, title, summary, body_markdown, category,
    author_partner_id, visibility,
    ai_instructions, ai_context_tags, status, is_verified, version, published_at
  ) VALUES (
    'external-observation-rides-one-shape',
    'External observation rides one shape',
    'Everything arriving from outside is information about an entity. Transport, parsing and identity signals vary per vendor; the storage shape does not. A new vendor is a value in a source column, never a new table family or service.',
    E'# External observation rides one shape\n\nEverything that arrives from outside is **information about an entity**. Ingest attaches it, and the twin reality grows autonomously as a consequence — not because someone declared new tables.\n\n```\n(source, observation, identity signals)  ->  identity resolution  ->  attach to twin\n```\n\n## Only three things vary per vendor\n\n1. **transport** — REST, SOAP, XLS, a person with a phone, an IoT gateway\n2. **parsing** — what each field means\n3. **identity signals** — plate, company id, VIN, sha256, sensor code\n\n**The storage shape is not one of them.** A vendor is a value in a `source` column. `production_sensor_readings.source` already proves the pattern: `homeassistant | manual | plc | lims | iot_gateway | scada` — a human-entered reading and a SCADA tag are the same row shape, because a measurement is a SIGNAL and the human is merely its TRANSPORT.\n\n## The measured violation (2026-07-26)\n\nThree carriers for one domain — vehicles, drivers, rides, odometer, distance:\n\n| carrier | transport | status |\n|---|---|---|\n| `services/svc-webdispecink` | SOAP `_getCarLogBook4` | dead endpoint |\n| `services/svc-tcars` | mirrored `tc_*` tables | upstreamed |\n| `plugins/eurowag-telematics` | REST trips/vehicles/drivers | built same day |\n\nTwo of them within 24 hours by the same author. Each vendor presented itself as "an integration", so each got its own carrier — and the duplication was invisible because it arrived in pieces from different directions.\n\n## Where the pieces actually belong\n\n- **raw lane** — the observation as received, specialised by the NATURE of the signal (typed numeric telemetry queries differently than an OCR''d document with a review state), never by WHO sent it\n- **identity** — `twin_external_refs`, not a mirrored foreign integer id. A vendor''s primary key is just one more identity signal, and a weak one\n- **derivative** — `twin_events` via the `(source, event_type, source_ref)` seam: a trip becomes an event with duration, place and relations\n\n## The tell\n\nIf you are about to create a table group, an enum, or a service whose NAME encodes a vendor, stop. Ask which existing lane carries this class of signal, and what makes this vendor''s row genuinely a different SHAPE rather than a different VALUE. Usually nothing does.',
    'integration_pattern'::expert_rule_category,
    v_partner_id, 'public',
    E'RULE: Everything arriving from outside is information about an entity, stored in one shape: (source, observation, identity signals) -> identity resolution -> attach to twin. Per vendor only three things vary — transport (REST/SOAP/XLS/human/IoT), parsing (field meaning), identity signals (plate, company id, VIN, sha256, sensor code). The storage shape NEVER varies: a new vendor is a value in a source column, not a new table family and not a new service. Precedent: production_sensor_readings.source already enumerates homeassistant|manual|plc|lims|iot_gateway|scada. Measured violation 2026-07-26: svc-webdispecink (SOAP) + svc-tcars (tc_* tables) + plugins/eurowag-telematics (REST) are three carriers for ONE domain (vehicle log book), two built within 24 hours. Before creating any table group, enum or service whose name encodes a vendor, name the existing lane that carries this class of signal and state what makes this a different SHAPE rather than a different VALUE. Identity goes in twin_external_refs — never mirror the vendor primary key as a column and never add an FK-gap allowlist entry to make mirrored ids pass; the vendor key is one weak identity signal among several. Specialise a lane by the NATURE of the signal (typed telemetry vs reviewable document), never by its sender.',
    ARRAY['architecture','ingest','twins','integration','identity','source_type:internal','data_sensitivity:public','retention_class:long_term','legal_basis:legitimate_interest'],
    'published', false, 1, now()
  ) ON CONFLICT (slug) DO UPDATE SET
    ai_instructions = EXCLUDED.ai_instructions,
    ai_context_tags = EXCLUDED.ai_context_tags,
    body_markdown = EXCLUDED.body_markdown,
    summary = EXCLUDED.summary,
    status = 'published',
    updated_at = now();

  -- 3. The meta-rule both collisions reduce to.
  INSERT INTO expert_rules (
    slug, title, summary, body_markdown, category,
    author_partner_id, visibility,
    ai_instructions, ai_context_tags, status, is_verified, version, published_at
  ) VALUES (
    'name-the-spine-before-building-a-carrier',
    'Name the spine before building a carrier',
    'The first question for any new capability is not how to build it but which existing spine it rides and whether the shape reaches the far end. New services and table families are the anti-pattern; the default answer is a row, a value, or a registration.',
    E'# Name the spine before building a carrier\n\nThe platform is extended by **declaring into something that already resolves**, not by adding carriers. Before writing a service, a table family, or a manifest, answer three questions in order:\n\n1. **Which existing spine does this ride?** Name it concretely — `plugin manifest -> materializer -> registry -> resolver`, or `(source, observation, identity signals) -> twin`, or `surface_blocks.source_params -> get_block_data`.\n2. **Does my shape reach the far end?** Not "does it validate" — does something on the other side actually consume it? Find the consumer and name it.\n3. **What makes this genuinely a new SHAPE and not a new VALUE?** If the honest answer is "the vendor is different" or "the protocol is different", it is a value.\n\nIf you cannot name the spine, you have not finished analysing — you have started building.\n\n## Why this keeps being violated\n\nBoth 2026-07-26 collisions were committed by an author who had been told all day not to build bespoke. Neither felt like bespoke at the time:\n\n- The extension **arrived as a vendor integration**, and integrations feel like they deserve their own module.\n- The duplication **arrived in pieces**, days apart, from different directions — so no single moment looked like "I am building the third one of these".\n\nThe defence is not vigilance, it is the question. Name the spine, in writing, before the first file.\n\n## The green-artifact failure mode\n\nThe expensive version of this mistake is not a rejected build — it is an accepted one. A manifest against a dead kind, a Traefik label that never matches, a config value nobody reads: all validate, all submit, all look done. **A thing wired to nothing reports success.** So "it built" and "it deployed" are not evidence; the evidence is the consumer doing something observable.\n\nRelated: `declared-extension-must-reach-the-resolver`, `external-observation-rides-one-shape`, `coolify-no-hostname-in-traefik-label`.',
    'architecture_pattern'::expert_rule_category,
    v_partner_id, 'public',
    E'RULE: Before writing a new service, table family, enum, or manifest, name in writing (a) which existing spine it rides, (b) which consumer on the far end will actually read it, (c) what makes it a new SHAPE rather than a new VALUE. If the differentiator is "different vendor" or "different protocol", it is a VALUE — a row or an enum entry — not a carrier. Known spines: plugin manifest -> materialize_* -> registry row -> aisha_resolve_clow_backend; (source, observation, identity signals) -> identity resolution -> twin; surface_blocks.source_params -> get_block_data. If you cannot name the spine you have not finished analysing. CRITICAL: a thing wired to nothing reports SUCCESS — manifests validate, builds pass, deploys go green while the far end never calls. Never accept "it built" or "it submitted" as evidence of wiring; the evidence is the consumer doing something observable. This rule exists because two violations were committed in one day by an author actively trying to avoid bespoke work: an integration presented itself as deserving its own module, and a triplication accumulated in pieces days apart so no single commit looked like the third copy.',
    ARRAY['architecture','doctrine','extension','reuse','analysis','source_type:internal','data_sensitivity:public','retention_class:long_term','legal_basis:legitimate_interest'],
    'published', false, 1, now()
  ) ON CONFLICT (slug) DO UPDATE SET
    ai_instructions = EXCLUDED.ai_instructions,
    ai_context_tags = EXCLUDED.ai_context_tags,
    body_markdown = EXCLUDED.body_markdown,
    summary = EXCLUDED.summary,
    status = 'published',
    updated_at = now();

END $seed$;


-- File: core/41_aisha_knowledge_from_experience.sql
