UPDATE archive_documents SET summary_key = 'archive.' || slug || '.summary' WHERE summary_key IS NULL;
UPDATE archive_documents SET editorial_note_key = 'archive.' || slug || '.editorial_note' WHERE editorial_note_key IS NULL;
